import pyomo.environ as pyo

DATA = {
    "assets": ["X", "Y", "Z"],
    "unit_cost": {"X": 500, "Y": 300, "Z": 700},
    "min_invest": {"X": 200, "Y": 150, "Z": 250},
    "budget": 1000,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Set of assets
    model.I = pyo.Set(initialize=d["assets"])

    # Decision: integer amount invested in each asset, with viability lower bounds
    def invest_bounds(m, i):
        return (d["min_invest"][i], None)

    model.invest = pyo.Var(
        model.I,
        domain=pyo.NonNegativeIntegers,
        bounds=invest_bounds,
    )

    # Objective: minimize total cost
    def obj_rule(m):
        return sum(d["unit_cost"][i] * m.invest[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Budget constraint: total investment cannot exceed budget
    def budget_rule(m):
        return sum(m.invest[i] for i in m.I) <= d["budget"]

    model.budget = pyo.Constraint(rule=budget_rule)

    return model


